import os, stat

for p in ['/work', '/work/CLAUDE.md', '/work/AGENTS.md']:
    try:
        st = os.lstat(p)
        print(p, 'exists', 'mode=%o' % stat.S_IMODE(st.st_mode), 'is_symlink=', stat.S_ISLNK(st.st_mode), 'is_dir=', stat.S_ISDIR(st.st_mode), 'uid=', st.st_uid)
        if stat.S_ISLNK(st.st_mode):
            print('  symlink target:', os.readlink(p))
    except FileNotFoundError:
        print(p, 'does not exist')

print()
print(os.listdir('/work'))
